steps.content:
# PowerShell, not POSIX sh: run this in PowerShell or Windows Terminal. In
# cmd.exe, Git Bash or WSL it will not work — Git Bash and WSL want the
# macOS/Linux/WSL snippet instead.
irm https://claude.ai/install.ps1 | iex

# The installer puts claude.exe under %USERPROFILE%\.local\bin and adds that
# directory to your user PATH, but this session read PATH before that happened.
$bin = Join-Path $env:USERPROFILE '.local\bin'
if (Test-Path $bin) { $env:Path = "$bin;$env:Path" }

if (Get-Command claude -ErrorAction SilentlyContinue) {
  claude --version
} else {
  Write-Warning "Installed, but 'claude' is not on this session's PATH yet. Open a new PowerShell window and run: claude --version"
}
